-- Import des tirelires depuis Notion (base « 🏛️ Tirelires Rengo »), extrait le 28/09/2026.
-- À coller dans Supabase > SQL Editor > New query > Run.
-- Le script peut être relancé sans créer de doublons (colonne notion_id).
--
-- Correspondance :
--   Entreprise              -> entreprise
--   Ville                   -> ville
--   Localisation GPS        -> adresse, lat, lng (vide si pas de position dans Notion)
--   Date de dernière action -> date_pose (à défaut : date de création de la fiche Notion)
--
-- Non importées : 2 fiches sans nom, « test », « À compléter »,
-- « Bro'okah vend chicha (à supprimé) ».

-- 1. Adapter la table : position facultative + identifiant Notion
alter table tirelires alter column lat drop not null;
alter table tirelires alter column lng drop not null;
alter table tirelires add column if not exists notion_id text unique;

-- 2. Importer les 206 tirelires
insert into tirelires (notion_id, entreprise, ville, adresse, lat, lng, date_pose) values
